def PrintedMatrixNormBounds {n : ℕ} (q : Matrix (Fin n) (Fin n) B → ℝ) : Prop :=
  (∀ M i j, ‖M i j‖ ≤ q M) ∧
    ∀ M, q M ≤ ∑ i, ∑ j, ‖M i j‖

